  <script>
    document.addEventListener(\'DOMContentLoaded\', function () {
      const club = document.querySelector(\'.course-club\');
      if (!club) return;

      const toggle = club.querySelector(\'.course-club__toggle\');
      const panel = club.querySelector(\'.course-club__panel\');

      function openPanel() {
        toggle.setAttribute(\'aria-expanded\', \'true\');
        panel.setAttribute(\'aria-hidden\', \'false\');
        panel.classList.add(\'is-open\');
        panel.style.height = panel.scrollHeight + \'px\';

        const onOpened = function () {
          if (toggle.getAttribute(\'aria-expanded\') === \'true\') {
            panel.style.height = \'auto\';
          }
          panel.removeEventListener(\'transitionend\', onOpened);
        };
        panel.addEventListener(\'transitionend\', onOpened);
      }

      function closePanel() {
        panel.style.height = panel.scrollHeight + \'px\';
        panel.offsetHeight;
        toggle.setAttribute(\'aria-expanded\', \'false\');
        panel.setAttribute(\'aria-hidden\', \'true\');
        panel.style.height = \'0px\';
        panel.classList.remove(\'is-open\');
      }

      toggle.addEventListener(\'click\', function () {
        const isOpen = toggle.getAttribute(\'aria-expanded\') === \'true\';
        isOpen ? closePanel() : openPanel();
      });

      window.addEventListener(\'resize\', function () {
        if (toggle.getAttribute(\'aria-expanded\') === \'true\' && panel.style.height !== \'auto\') {
          panel.style.height = panel.scrollHeight + \'px\';
        }
      });
    });
  </script>

